use mushroom_solar::{annual_electrical_adapter::{join_and_evaluate,AnnualAdapterConfig,AnnualIrradianceRow},electrical::ElectricalDesignBasis,thermal::NmotParameters,weather::WeatherRecord};
fn w(t:i64,ta:f64)->WeatherRecord{WeatherRecord{timestamp:format!("{t}"),timestamp_utc_s:t,ghi_w_m2:0.,dhi_w_m2:0.,dni_w_m2:0.,ambient_temperature_c:ta,wind_speed_m_s:0.,wind_direction_deg:0.,relative_humidity_percent:None,air_pressure_pa:None,provider_quality_flag:None}}
fn main(){println!("timestamp_utc_s,candidate,resource_contract,poa_w_m2,ambient_temp_c,nmot_c,module_temp_c,eta,p_dc_w,p_ac_w,p_aux_w,p_net_w,dt_h,e_net_wh,design_basis,status");
let r=[(0,0.,27.),(3600,400.,30.),(7200,800.,31.)];let ir:Vec<_>=r.iter().map(|(t,g,_)|AnnualIrradianceRow{timestamp_utc_s:*t,geometry:"synthetic_flat".into(),resource_contract:"synthetic_equal_land".into(),poa_w_m2:*g,accepted:true,irradiance_provenance:"SYNTHETIC_ADAPTER_VALIDATION".into()}).collect();let wr:Vec<_>=r.iter().map(|(t,_,ta)|w(*t,*ta)).collect();let e=ElectricalDesignBasis::canadian_solar_cs62_48tm_460h();
for nmot in [39.,42.,45.]{let cfg=AnnualAdapterConfig{nmot:NmotParameters{nmot_c:nmot,reference_ambient_c:20.,reference_irradiance_w_m2:800.},nmot_scenario_c:nmot,dt_hours:1.,auxiliary_power_w:0.,design_basis_id:"CS6.2-48TM-460H".into(),status:"DEVELOPMENT_NOT_SERIS_SYNTHETIC_ADAPTER_VALIDATION_NOT_AN_ANNUAL_PERFORMANCE_RESULT".into()};for o in join_and_evaluate(&ir,&wr,&cfg,&e,"SYNTHETIC_WEATHER").unwrap(){println!("{},{},{},{:.3},{:.3},{:.1},{:.6},{:.12},{:.6},{:.6},{:.6},{:.6},{:.3},{:.6},{},{}",o.timestamp_utc_s,o.geometry,o.resource_contract,o.poa_w_m2,o.ambient_temp_c,o.nmot_c,o.module_temp_c,o.efficiency,o.delivered_dc_w,o.ac_w,o.auxiliary_power_w,o.net_w,o.dt_hours,o.net_energy_wh,o.design_basis_id,o.status);}}}